// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 beforeReported;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeReported = __r; } catch { return; }
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;
        bool depositReverted;
        try c.addToBalance{value: deposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }
        uint256 afterReported;
        try c.getBalance(address(this)) returns (uint256 __r) { afterReported = __r; } catch { return; }
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 finalReported;
        try c.getBalance(address(this)) returns (uint256 __r) { finalReported = __r; } catch { return; }
        uint finalCbal = address(c).balance;
        uint finalThis = address(this).balance;
        assertTrue((!withdrawReverted && (finalThis - afterThis == afterReported) && (afterCbal - finalCbal >= afterReported) && finalReported == 0)
            || (withdrawReverted && finalReported == afterReported && finalCbal == afterCbal && finalThis == afterThis));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
